import { STRUDEL_API } from "../strudelApi";
import raw from "./apiDocs.json";

/**
 * Reference of every function Over Strudel accepts. The text comes from the documentation that ships with the Strudel
 * packages (generated by scripts/gen-api-docs.mjs, English) and is completed here, in Spanish, for the functions the
 * packages do not document (operators, REPL functions, the functions Over Strudel adds, device/visual stubs).
 */
export interface FnDoc {
  name: string;
  aliases: string[];
  category: string;
  description: string;
  params: { type: string; name: string; desc: string }[];
  examples: string[];
  /** where the text comes from */
  source: "strudel" | "over-strudel" | "none";
  /** true when the function only acts on sound, visuals or devices (the score ignores it) */
  scoreNeutral?: boolean;
}

interface Extra {
  d: string;
  ex?: string[];
  cat?: string;
  neutral?: boolean;
  ours?: boolean;
}

const ops = (names: string[], what: string, ex: string): Record<string, Extra> =>
  Object.fromEntries(names.map((n) => [n, { d: what, ex: [ex], cat: "Operadores" }]));

