/** Sensors: constant 0 in the notation. */
for (const n of ["absoluteOrientationAlpha", "absoluteOrientationBeta", "absoluteOrientationGamma", "accelerationX", "accelerationY", "accelerationZ", "gravityX", "gravityY", "gravityZ", "orientationAlpha", "orientationBeta", "orientationGamma", "rotationAlpha", "rotationBeta", "rotationGamma"]) {
  EXTRA[n] = { cat: "Sensores", neutral: true, d: "Valor del sensor de movimiento del dispositivo como señal continua. En la partitura vale siempre 0." };
}

/** Where a function without an explicit category goes, by its name and the file it was documented in. */
function categoryOf(name: string, file?: string, area?: string): string {
  const n = name.toLowerCase();
  if (file === "signal.mjs") return "Señales y azar";
  if (file === "euclid.mjs") return "Ritmo";
  if (file === "pick.mjs") return "Combinar patrones";
  if (file === "tonal.mjs" || file === "voicings.mjs") return "Armonía y escalas";
  if (area === "visual" || file === "scope.mjs" || file === "spectrum.mjs") return "Visualización";
  if (/^(note|n|freq|detune|vib|vibmod|unison|fm|octave|accelerate|penv|pattack|pdecay|prelease|psustain|ftype|tune)/.test(n) || /^(fm\w*)$/.test(n)) return "Altura y síntesis";
  if (/(attack|decay|sustain|release|adsr|^att$|^dec$|^rel$|^sus$|^env$)/.test(n) && !/^duck/.test(n)) return "Envolventes";
  if (/^duck|^orbit|^compressor|^postgain|^gain$|^velocity|^vel$|^xfade|^pan|^amp/.test(n)) return "Mezcla y dinámica";
  if (/^(lp|hp|bp|lpf|hpf|bpf|cutoff|resonance|djf|vowel|ftype|bandf|bandq|eq|filter)/.test(n) && !/^filterhaps|^filtervalues|^filterwhen/.test(n)) return "Filtros";
  if (/^(delay|room|rsize|rlp|rfade|rdim|reverb|phaser|ph|chorus|dist|shape|crush|coarse|tremolo|trem|dry|leslie|ring|comb|lfo|orbit|jux)/.test(n) || /^(sz|size|iresponse|ir|irspeed|irbegin)/.test(n)) return "Efectos";
  if (/^(begin|end|loop|chop|slice|splice|speed|cut|clip|legato|striate|scrub|bank|sound|s$|unit|stretch|fit|loopat)/.test(n)) return "Muestras";
  if (/^(wt|warp|wavetable)/.test(n)) return "Wavetables";
  if (/^(midi|ccn|ccv|nrpn|nrpv|sysex|prognum|channel|osc)/.test(n)) return "Dispositivos";
  if (/^(rand|perlin|choose|wchoose|shuffle|scramble|degrade|undegrade|sometimes|somecycles|often|rarely|always|never|almost|brand|irand|seed)/.test(n)) return "Señales y azar";
  if (/^(fast|slow|early|late|hurry|ply|segment|swing|linger|range|compress|zoom|inside|outside|off|echo|stut|iter|palindrome|rev|chunk|every|firstof|lastof|when|within|press|brak|loopat|run|binary|euclid|struct|mask|beat|bite|squeeze|focus|expand|extend|take|drop|repeat|pace|stepcat|stepalt|tour|fastgap|swingby|ribbon|rib)/.test(n)) return "Tiempo y estructura";
  if (/^(stack|cat|seq|slowcat|fastcat|polymeter|pm|arrange|layer|superimpose|set|keep|pick|inhabit|squeeze|apply|as|fit|zip|morph)/.test(n)) return "Combinar patrones";
  if (/^(with|filter|queryarc|first|show|strip|defragment|remove|split|discrete|onsets|sort|log)/.test(n)) return "Funciones internas";
  return "Otras";
}

export const CATEGORY_ORDER = [
  "REPL y tempo", "Tiempo y estructura", "Ritmo", "Combinar patrones", "Operadores", "Señales y azar", "Altura y síntesis", "Armonía y escalas",
  "Envolventes", "Filtros", "Efectos", "Mezcla y dinámica", "Estéreo", "Muestras", "Sonidos", "Wavetables", "Visualización", "Dispositivos", "Sensores", "Color", "Funciones internas", "Otras",
];

type Raw = { name: string; synonyms: string[]; description: string; params: FnDoc["params"]; examples: string[]; area: string; file: string };
const byName = new Map<string, Raw>();
for (const r of raw as Raw[]) {
  byName.set(r.name, r);
  for (const s of r.synonyms) if (!byName.has(s)) byName.set(s, r);
}

const clean = (t: string) => t.replace(/\{@link ([^}]+)\}/g, "$1").trim();

export const FUNCTION_DOCS: FnDoc[] = STRUDEL_API.map((row) => {
  const main = row[0];
  const rowNames = row.slice();
  const extra = rowNames.map((n) => EXTRA[n]).find(Boolean);
  const r = rowNames.map((n) => byName.get(n)).find(Boolean);
  const description = extra?.d ? clean(extra.d) : r ? clean(r.description) : "";
  return {
    name: main,
    aliases: row.slice(1),
    category: extra?.cat ?? categoryOf(main, r?.file, r?.area),
    description: description || "Sin descripción en la documentación de Strudel (función de bajo nivel o de uso interno).",
    params: r?.params ?? [],
    examples: extra?.ex ?? r?.examples ?? [],
    source: extra?.ours ? "over-strudel" : description ? "strudel" : "none",
    scoreNeutral: extra?.neutral,
  };
});
